module.exports = "<ion-header class=\"interior-header\" [attr.dir]=\"language.direction\">\n  \n  <app-page-header titleKey=\"pageHeader.article/article\" fallback=\"/\">\n<div page-actions><button type=\"button\" class=\"icon-button search-toggle\" (click)=\"showSearchbar = !showSearchbar\" [attr.aria-expanded]=\"showSearchbar\" aria-label=\"جستجو در سامانه\" title=\"جستجو در سامانه\">\r\n        <ion-icon name=\"search-outline\" aria-hidden=\"true\"></ion-icon>\r\n      </button>\n</div>\n\n<div class=\"header-search-bar\" *ngIf=\"showSearchbar\">\r\n    <div class=\"search-input-wrap\">\r\n      <ion-icon name=\"search-outline\" aria-hidden=\"true\"></ion-icon>\r\n      <input type=\"search\" [(ngModel)]=\"queryText\" [placeholder]=\"'search.academy' | translate\" (keyup.enter)=\"search()\" autofocus />\r\n      <button type=\"button\" class=\"action-btn primary\" (click)=\"search()\">{{ 'common.search' | translate }}</button>\r\n      <button type=\"button\" class=\"action-btn ghost\" (click)=\"onCancel()\">{{ 'search.cancel' | translate }}</button>\r\n    </div>\r\n  </div>\n  </app-page-header>\n</ion-header>\r\n\r\n<ion-content class=\"article-catalog-content\" [attr.dir]=\"language.direction\">\r\n  <ion-refresher slot=\"fixed\" (ionRefresh)=\"doRefresh($event)\">\r\n    <ion-refresher-content></ion-refresher-content>\r\n  </ion-refresher>\r\n\r\n  <div class=\"page-wrapper\">\r\n    <!-- Ambient Backdrop Glows -->\r\n    <div class=\"backdrop-glows\" aria-hidden=\"true\">\r\n      <div class=\"glow-orb glow-purple\"></div>\r\n      <div class=\"glow-orb glow-amber\"></div>\r\n      <div class=\"glow-orb glow-emerald\"></div>\r\n    </div>\r\n\r\n    <!-- Playful Floating Elementary Decor -->\r\n    <span class=\"floating-decor book\" aria-hidden=\"true\">📚</span>\r\n    <span class=\"floating-decor star\" aria-hidden=\"true\">✦</span>\r\n    <span class=\"floating-decor pencil\" aria-hidden=\"true\">✏️</span>\r\n    <span class=\"floating-decor sparkle\" aria-hidden=\"true\">✨</span>\r\n\r\n    <main class=\"article-main\">\r\n      <!-- Hero Section -->\r\n      <section class=\"article-hero\">\r\n        <div class=\"hero-shell\">\r\n          <div class=\"eyebrow-wrap\">\r\n            <span class=\"eyebrow\">\r\n              <span class=\"little-star\">✦</span>\r\n              {{ 'catalog.articleSubtitle' | translate }}\r\n            </span>\r\n            <span class=\"hero-chip\">\r\n              <ion-icon name=\"school-outline\" aria-hidden=\"true\"></ion-icon>\r\n              مقالات تخصصی و ایده‌های تدریس ابتدایی\r\n            </span>\r\n          </div>\r\n\r\n          <h1>\r\n            دانش‌افزایی و روش‌های نوین تدریس:<br />\r\n            <span class=\"highlight\">\r\n              {{ 'catalog.articles' | translate }}\r\n              <svg viewBox=\"0 0 360 20\" aria-hidden=\"true\">\r\n                <path d=\"M5 13Q170 -5 355 10M30 18Q190 2 328 16\" />\r\n              </svg>\r\n            </span>\r\n          </h1>\r\n\r\n          <p class=\"hero-desc\">\r\n            مجموعه جامع مقالات آموزشی، راهنمای تدریس خلاق الفبا و ریاضی، مدیریت رفتار در کلاس اول دبستان و نکات کاربردی برای آموزگاران و والدین.\r\n          </p>\r\n\r\n          <!-- Modern Search Bar -->\r\n          <div class=\"article-search-shell\">\r\n            <div class=\"article-search-input\">\r\n              <ion-icon name=\"search-outline\" aria-hidden=\"true\"></ion-icon>\r\n              <input\r\n                type=\"text\"\r\n                [(ngModel)]=\"articleSearch\"\r\n                (keyup.enter)=\"setQueryParams(1)\"\r\n                [placeholder]=\"'catalog.searchArticles' | translate\"\r\n              />\r\n              <button *ngIf=\"articleSearch\" type=\"button\" class=\"clear-btn\" (click)=\"articleSearch = ''; setQueryParams(1)\" title=\"پاک کردن\">\r\n                <ion-icon name=\"close-circle\" aria-hidden=\"true\"></ion-icon>\r\n              </button>\r\n              <button type=\"button\" class=\"search-submit-btn\" (click)=\"setQueryParams(1)\">\r\n                <ion-icon name=\"search-outline\" aria-hidden=\"true\"></ion-icon>\r\n                <span>جستجو</span>\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Quick Topic Chips -->\r\n          <div class=\"quick-topics-row\">\r\n            <span class=\"quick-title\">موضوعات پرطرفدار:</span>\r\n            <button type=\"button\" class=\"quick-chip\" (click)=\"quickFilter('الفبا')\">تدریس الفبا و نشانه‌ها</button>\r\n            <button type=\"button\" class=\"quick-chip\" (click)=\"quickFilter('ریاضی')\">بازی‌های ریاضی اول</button>\r\n            <button type=\"button\" class=\"quick-chip\" (click)=\"quickFilter('طرح درس')\">طرح‌درس‌نویسی</button>\r\n            <button type=\"button\" class=\"quick-chip\" (click)=\"quickFilter('مدیریت کلاس')\">مدیریت رفتار دانش‌آموزان</button>\r\n            <button type=\"button\" class=\"quick-chip\" (click)=\"quickFilter('کاربرگ')\">کاربرگ‌های هفتگی</button>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      <!-- Articles Section -->\r\n      <section class=\"articles-catalog-section\" aria-labelledby=\"catalog-title\">\r\n        <div class=\"catalog-heading-row\">\r\n          <div>\r\n            <span class=\"section-kicker\"><span class=\"kicker-sparkle\">✦</span> آرشیو مقالات</span>\r\n            <h2 id=\"catalog-title\">تازه‌ترین مقالات منتشر شده</h2>\r\n          </div>\r\n          <span class=\"results-badge\" *ngIf=\"filteredArticles?.articles\">\r\n            صفحه {{ filteredArticles.pageId }} از {{ filteredArticles.pageCount }}\r\n          </span>\r\n        </div>\r\n\r\n        <!-- Active Filter Indicator if searching -->\r\n        <div class=\"active-filter-bar\" *ngIf=\"articleSearch\">\r\n          <span>نتایج جستجو برای: <b>«{{ articleSearch }}»</b></span>\r\n          <button type=\"button\" class=\"remove-filter-btn\" (click)=\"articleSearch = ''; setQueryParams(1)\">\r\n            <ion-icon name=\"close-outline\"></ion-icon>\r\n            <span>نمایش همه مقالات</span>\r\n          </button>\r\n        </div>\r\n\r\n        <!-- Articles Grid -->\r\n        <div class=\"articles-grid\" *ngIf=\"filteredArticles?.articles?.length\">\r\n          <div class=\"article-grid-col\" *ngFor=\"let article of filteredArticles.articles\">\r\n            <app-article [article]=\"article\"></app-article>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Loading State -->\r\n        <div class=\"catalog-loading\" *ngIf=\"!filteredArticles?.articles\">\r\n          <ion-spinner name=\"bubbles\" color=\"primary\"></ion-spinner>\r\n          <span>در حال دریافت مقالات آموزشی...</span>\r\n        </div>\r\n\r\n        <!-- Empty State -->\r\n        <div class=\"catalog-empty-state\" *ngIf=\"filteredArticles?.articles && filteredArticles.articles.length === 0\">\r\n          <div class=\"empty-icon\">🎒</div>\r\n          <h3>مقاله‌ای با این مشخصات یافت نشد</h3>\r\n          <p>می‌توانید عبارت جستجو را تغییر دهید یا همه مقالات را مشاهده فرمایید.</p>\r\n          <button type=\"button\" class=\"button primary small\" (click)=\"articleSearch = ''; setQueryParams(1)\">\r\n            نمایش همه مقالات\r\n          </button>\r\n        </div>\r\n\r\n        <!-- Modern Pagination -->\r\n        <nav class=\"modern-pagination\" *ngIf=\"filteredArticles?.pageCount > 1\" aria-label=\"صفحه‌بندی مقالات\">\r\n          <button\r\n            type=\"button\"\r\n            class=\"page-btn page-nav-arrow\"\r\n            [disabled]=\"filteredArticles.pageId <= 1\"\r\n            (click)=\"goPreviousPage()\"\r\n            title=\"صفحه قبلی\"\r\n          >\r\n            <ion-icon name=\"arrow-forward-outline\"></ion-icon>\r\n            <span>قبلی</span>\r\n          </button>\r\n\r\n          <!-- First Page Jump -->\r\n          <button\r\n            *ngIf=\"filteredArticles.pageId > 2\"\r\n            type=\"button\"\r\n            class=\"page-btn\"\r\n            (click)=\"goPage(1)\"\r\n          >\r\n            1\r\n          </button>\r\n          <span *ngIf=\"filteredArticles.pageId > 3\" class=\"page-ellipsis\">...</span>\r\n\r\n          <!-- Numbered Pages -->\r\n          <ng-container *ngFor=\"let page of MakePageCountArray(filteredArticles.pageCount); let i = index\">\r\n            <button\r\n              *ngIf=\"(i + 1) >= (filteredArticles.pageId - 1) && (i + 1) <= (filteredArticles.pageId + 1)\"\r\n              type=\"button\"\r\n              class=\"page-btn\"\r\n              [class.active]=\"filteredArticles.pageId == (i + 1)\"\r\n              (click)=\"goPage(i + 1)\"\r\n            >\r\n              {{ i + 1 }}\r\n            </button>\r\n          </ng-container>\r\n\r\n          <span *ngIf=\"filteredArticles.pageId < (filteredArticles.pageCount - 2)\" class=\"page-ellipsis\">...</span>\r\n          <!-- Last Page Jump -->\r\n          <button\r\n            *ngIf=\"filteredArticles.pageId < (filteredArticles.pageCount - 1)\"\r\n            type=\"button\"\r\n            class=\"page-btn\"\r\n            (click)=\"goPage(filteredArticles.pageCount)\"\r\n          >\r\n            {{ filteredArticles.pageCount }}\r\n          </button>\r\n\r\n          <button\r\n            type=\"button\"\r\n            class=\"page-btn page-nav-arrow\"\r\n            [disabled]=\"filteredArticles.pageId >= filteredArticles.pageCount\"\r\n            (click)=\"goNextPage()\"\r\n            title=\"صفحه بعدی\"\r\n          >\r\n            <span>بعدی</span>\r\n            <ion-icon name=\"arrow-back-outline\"></ion-icon>\r\n          </button>\r\n        </nav>\r\n      </section>\r\n\r\n      <!-- Teacher Contribution Banner -->\r\n      <section class=\"contribution-banner\">\r\n        <div class=\"contribution-copy\">\r\n          <span class=\"contribution-kicker\">✦ همکاری علمی و تالیف</span>\r\n          <h3>تجربیات و مقالات آموزشی خود را در اول آموز منتشر کنید</h3>\r\n          <p>آموزگاران و سرگروه‌های آموزشی می‌توانند مقالات تخصصی و روش‌های تدریس خلاق خود را با هزاران همکار در سراسر کشور به اشتراک بگذارند.</p>\r\n        </div>\r\n        <a routerLink=\"/Suport\" class=\"button primary\">\r\n          <ion-icon name=\"paper-plane-outline\"></ion-icon>\r\n          <span>ارسال مقاله یا پیشنهاد همکاری</span>\r\n        </a>\r\n      </section>\r\n    </main>\r\n  </div>\r\n\r\n  <app-footer></app-footer>\r\n</ion-content>\r\n";

